/*
|--------------------------------------------------------------------------
| TEMANDENGAR - VALIDATE JOURNAL REQUEST
|--------------------------------------------------------------------------
|
| Tujuan:
| 1. Mengambil data jurnal dari Webhook.
| 2. Memvalidasi journal_id.
| 3. Memvalidasi title dan entry_type.
| 4. Memvalidasi mood.
| 5. Memvalidasi isi jurnal.
| 6. Menghasilkan data yang sudah dinormalisasi.
|
| Output:
| - is_valid: true / false
| - error: informasi kesalahan jika tidak valid
| - data: data jurnal jika valid
|
|--------------------------------------------------------------------------
*/

// 1. Ambil data dari node Webhook.
const webhookItem = $input.first()?.json ?? {};

// Webhook n8n menempatkan payload request di properti body.
let body = webhookItem.body ?? webhookItem;

// 2. Pastikan body berbentuk JSON object.
if (typeof body === 'string') {
    try {
        body = JSON.parse(body);
    } catch (error) {
        body = null;
    }
}

// 3. Siapkan penampung error validasi.
const errors = [];

// 4. Pastikan body merupakan object yang valid.
if (
    !body ||
    typeof body !== 'object' ||
    Array.isArray(body)
) {
    return [
        {
            json: {
                is_valid: false,
                error: {
                    code: 'INVALID_REQUEST',
                    message: 'Format request tidak valid.',
                    details: ['Request body harus berupa JSON object.']
                },
                data: null
            }
        }
    ];
}

// 5. Validasi journal_id.
const journalId = Number(body.journal_id);

if (
    !Number.isSafeInteger(journalId) ||
    journalId <= 0
) {
    errors.push('journal_id harus berupa angka positif.');
}

// 6. Validasi title.
let title = null;

if (body.title !== undefined && body.title !== null) {
    if (typeof body.title !== 'string') {
        errors.push('title harus berupa teks.');
    } else {
        title = body.title.trim() || null;

        if (title && title.length > 160) {
            errors.push('title maksimal 160 karakter.');
        }
    }
}

// 7. Validasi entry_type.
const allowedEntryTypes = ['free', 'guided'];

const entryType = body.entry_type;

if (!allowedEntryTypes.includes(entryType)) {
    errors.push('entry_type harus free atau guided.');
}

// 8. Validasi mood.
const allowedMoods = [
    'senang',
    'tenang',
    'sedih',
    'cemas',
    'marah',
    'lelah',
    'bingung'
];

let mood = body.mood ?? null;

if (mood === '') {
    mood = null;
}

if (mood !== null && !allowedMoods.includes(mood)) {
    errors.push('Mood yang dikirim tidak tersedia.');
}

// 9. Validasi isi jurnal.
let content = '';

if (typeof body.content !== 'string') {
    errors.push('content harus berupa teks.');
} else {
    content = body.content.trim();

    if (content.length < 3) {
        errors.push('Isi jurnal minimal 3 karakter.');
    }

    if (content.length > 20000) {
        errors.push('Isi jurnal maksimal 20.000 karakter.');
    }
}

// 10. Validasi mood_note (opsional).
let moodNote = null;

if (body.mood_note !== undefined && body.mood_note !== null) {
    if (typeof body.mood_note !== 'string') {
        errors.push('mood_note harus berupa teks.');
    } else {
        moodNote = body.mood_note.trim() || null;

        if (moodNote && moodNote.length > 500) {
            errors.push('mood_note maksimal 500 karakter.');
        }
    }
}

// 11. Jika ditemukan kesalahan, kembalikan status invalid.
if (errors.length > 0) {
    return [
        {
            json: {
                is_valid: false,
                error: {
                    code: 'VALIDATION_ERROR',
                    message: 'Data jurnal tidak lolos validasi.',
                    details: errors
                },
                data: null
            }
        }
    ];
}

// 12. Jika valid, kembalikan data yang sudah dinormalisasi.
return [
    {
        json: {
            is_valid: true,
            error: null,

            data: {
                journal_id: journalId,
                title: title,
                entry_type: entryType,
                mood: mood,
                mood_note: moodNote,
                content: content
            }
        }
    }
];

const response = $input.first().json;

// Ambil journal_id dari Node 02
const validation = $('02 - Validate Journal Request').first().json;
const journalId = validation.data?.journal_id;

// Ambil isi jawaban Hermes
const rawContent = response.choices?.[0]?.message?.content;

function fail(message) {
  return {
    json: {
      success: false,
      journal_id: journalId ?? null,
      error: {
        code: 'INVALID_AI_RESPONSE',
        message
      },
      reflection: null
    }
  };
}

// Pastikan Hermes mengirimkan konten
if (typeof rawContent !== 'string' || !rawContent.trim()) {
  return [fail('Hermes tidak mengirimkan konten refleksi.')];
}

try {
  // Bersihkan kemungkinan Markdown code fence
  const cleanedContent = rawContent
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

  // Ubah JSON string menjadi object
  const reflection = JSON.parse(cleanedContent);

  // Validasi struktur respons
  const isValid =
    typeof reflection.summary === 'string' &&
    reflection.summary.trim().length > 0 &&
    typeof reflection.emotional_insight === 'string' &&
    reflection.emotional_insight.trim().length > 0 &&
    Array.isArray(reflection.key_concerns) &&
    reflection.key_concerns.length <= 3 &&
    reflection.key_concerns.every(item => typeof item === 'string') &&
    Array.isArray(reflection.reflection_questions) &&
    reflection.reflection_questions.length >= 2 &&
    reflection.reflection_questions.length <= 3 &&
    reflection.reflection_questions.every(item => typeof item === 'string') &&
    Array.isArray(reflection.suggested_steps) &&
    reflection.suggested_steps.length <= 3 &&
    reflection.suggested_steps.every(item => typeof item === 'string');

  if (!isValid) {
    return [fail('Struktur refleksi dari Hermes tidak sesuai format.')];
  }

  return [
    {
      json: {
        success: true,
        journal_id: journalId,
        error: null,
        reflection: {
          summary: reflection.summary,
          emotional_insight: reflection.emotional_insight,
          key_concerns: reflection.key_concerns,
          reflection_questions: reflection.reflection_questions,
          suggested_steps: reflection.suggested_steps
        }
      }
    }
  ];

} catch (error) {
  return [fail('Jawaban Hermes bukan JSON yang valid.')];
}

